using System;using System.Drawing;using System.Collections.Generic;using System.Linq;using System.IO;using System.Windows.Forms;
namespace IDSketcher {
partial class Document {void Set3DQuality(bool full){foreach(var layer in Layers)if(layer.Is3D&&layer.Scene.FullQuality!=full){layer.Scene.FullQuality=full;layer.InvalidateVectors();}}}
partial class Canvas {
 public bool Move3D;public Action ThreeDChanged;bool dragging3D,changed3D,moving3D;Point last3D;
 void BeginThreeD(MouseEventArgs e){if(Doc==null||!Doc.Selected.Is3D||Doc.Selected.IsLocked||!Doc.Selected.Visible||e.Button!=MouseButtons.Left&&e.Button!=MouseButtons.Right)return;dragging3D=true;changed3D=false;moving3D=Move3D||e.Button==MouseButtons.Right;last3D=e.Location;Capture=true;RefreshCursor();}
 bool MoveThreeD(MouseEventArgs e){if(Doc==null||!Doc.Selected.Is3D)return false;if(!dragging3D)return true;int dx=e.X-last3D.X,dy=e.Y-last3D.Y;if(dx==0&&dy==0)return true;if(Doc.Selected.IsLocked){EndThreeD();return true;}if(!changed3D){if(BeforeStroke!=null)BeforeStroke();changed3D=true;}var view=Doc.Selected.Scene;view.Interacting=true;if(moving3D){view.X+=dx/Zoom;view.Y+=dy/Zoom;}else{view.Yaw=(view.Yaw+dx*.6f)%360;view.Pitch=Math.Max(-89,Math.Min(89,view.Pitch+dy*.6f));}last3D=e.Location;Doc.Selected.InvalidateVectors();Invalidate();return true;}
 void EndThreeD(){if(!dragging3D)return;dragging3D=false;Capture=false;if(Doc!=null&&Doc.Selected.Is3D&&Doc.Selected.Scene.Interacting){Doc.Selected.Scene.Interacting=false;Doc.Selected.InvalidateVectors();Invalidate();}bool changed=changed3D;changed3D=false;if(changed&&AfterStroke!=null)AfterStroke();if(ThreeDChanged!=null)ThreeDChanged();}
 public void SetThreeDZoom(float scale){if(Doc==null||!Doc.Selected.Is3D||Doc.Selected.IsLocked)return;scale=Math.Max(.05f,Math.Min(20,scale));if(Math.Abs(scale-Doc.Selected.Scene.Scale)<.00001)return;if(BeforeStroke!=null)BeforeStroke();Doc.Selected.Scene.Scale=scale;Doc.Selected.InvalidateVectors();if(AfterStroke!=null)AfterStroke();if(ThreeDChanged!=null)ThreeDChanged();Invalidate();}
 void ZoomThreeD(float factor){SetThreeDZoom(Doc.Selected.Scene.Scale*factor);}
 public void ResetThreeD(){if(Doc==null||!Doc.Selected.Is3D||Doc.Selected.IsLocked)return;EndStroke();if(BeforeStroke!=null)BeforeStroke();var view=Doc.Selected.Scene;view.X=Doc.Width/2f;view.Y=Doc.Height/2f;view.Scale=1;view.Lens=50;view.Yaw=-25;view.Pitch=15;Doc.Selected.InvalidateVectors();if(AfterStroke!=null)AfterStroke();if(ThreeDChanged!=null)ThreeDChanged();Invalidate();}
 public void TestThreeDWheel(int delta){OnMouseWheel(new MouseEventArgs(MouseButtons.None,0,100,100,delta));}
}
partial class Studio {
 List<Control> threeDControls=new List<Control>();TrackBar threeDZoom,threeDLens;Label threeDLensLabel;Label threeDInfo,threeDZoomLabel,threeDCaptureInfo;Button threeDOrbit,threeDMove;bool syncingThreeD;
 void AddThreeDControls(FlowLayoutPanel panel){int start=panel.Controls.Count;panel.Controls.Add(new Label{Text="3D LAYER",Width=170,Height=28});threeDOrbit=Theme.Button("Orbit model",delegate{canvas.Move3D=false;SyncThreeDControls();canvas.Focus();canvas.RefreshCursor();});threeDMove=Theme.Button("Move on page",delegate{canvas.Move3D=true;SyncThreeDControls();canvas.Focus();canvas.RefreshCursor();});threeDOrbit.Width=threeDMove.Width=170;panel.Controls.Add(threeDOrbit);panel.Controls.Add(threeDMove);threeDZoomLabel=new Label{Text="MODEL ZOOM\n100%",Width=170,Height=38,Margin=new Padding(3,14,3,0)};panel.Controls.Add(threeDZoomLabel);threeDZoom=new TrackBar{Minimum=5,Maximum=2000,Value=100,Width=170,Height=30,AutoSize=false,TickStyle=TickStyle.None,SmallChange=5,LargeChange=25};threeDZoom.ValueChanged+=delegate{if(!syncingThreeD)canvas.SetThreeDZoom(threeDZoom.Value/100f);};panel.Controls.Add(threeDZoom);threeDLensLabel=new Label{Text="PERSPECTIVE\n50 MM",Width=170,Height=38};panel.Controls.Add(threeDLensLabel);threeDLens=new TrackBar{Minimum=30,Maximum=100,Value=50,Width=170,Height=30,AutoSize=false,TickStyle=TickStyle.None};threeDLens.ValueChanged+=delegate{if(!syncingThreeD)canvas.SetThreeDLens(threeDLens.Value);};panel.Controls.Add(threeDLens);var reset=Theme.Button("RESET MODEL",delegate{canvas.ResetThreeD();});reset.Width=170;panel.Controls.Add(reset);var capture=Theme.Button("Capture canvas",delegate{CaptureCanvasLayer();});capture.Width=170;capture.Height=38;capture.Margin=new Padding(3,18,3,3);panel.Controls.Add(capture);threeDCaptureInfo=new Label{Text="Captures become hidden pixel layers, ready to show or edit.",Width=170,Height=65};threeDInfo=new Label{Width=170,Height=70};panel.Controls.Add(threeDInfo);for(int i=start;i<panel.Controls.Count;i++)threeDControls.Add(panel.Controls[i]);canvas.ThreeDChanged=SyncThreeDControls;}
 void SyncThreeDControls(){if(threeDZoom==null||canvas.Doc==null||!canvas.Doc.Selected.Is3D)return;syncingThreeD=true;try{var layer=canvas.Doc.Selected;threeDLens.Value=(int)Math.Round(layer.Scene.Lens);threeDLensLabel.Text="PERSPECTIVE\n"+threeDLens.Value+" MM";threeDLens.Enabled=!layer.IsLocked;threeDZoom.Value=Math.Max(5,Math.Min(2000,(int)Math.Round(layer.Scene.Scale*100)));threeDZoomLabel.Text="MODEL ZOOM\n"+threeDZoom.Value+"%";threeDZoom.Enabled=threeDOrbit.Enabled=threeDMove.Enabled=!layer.IsLocked;threeDOrbit.BackColor=!canvas.Move3D?Theme.Accent:Theme.Panel;threeDMove.BackColor=canvas.Move3D?Theme.Accent:Theme.Panel;threeDInfo.Text=layer.Scene.Model.Triangles.Length.ToString("N0")+" triangles\nStatic model · embedded GLB"+(layer.Scene.Model.HasAnimations?"\nAnimation shown in base pose":"");}finally{syncingThreeD=false;}}
 void AddThreeDModel(GlbModel model,string name){if(canvas.Doc==null||canvas.Doc.Layers.Count>=32)return;canvas.EndStroke();var doc=canvas.Doc;var layer=new Layer("3D · "+(name.Length>160?name.Substring(0,160):name),doc.Width,doc.Height){Scene=new ThreeDView{Model=model,X=doc.Width/2f,Y=doc.Height/2f}};doc.Layers.Insert(doc.Active+1,layer);doc.Active++;canvas.Move3D=false;Changed();RefreshLayers();toolPanel.AutoScrollPosition=Point.Empty;canvas.Focus();}
 void CaptureCanvasLayer(){if(canvas.Doc==null||canvas.Doc.Layers.Count>=32){MessageBox.Show(this,"There is no room for another layer (maximum 32).");return;}canvas.EndStroke();try{UseWaitCursor=true;var doc=canvas.Doc;var capture=doc.Flatten();var layer=new Layer("Capture "+(doc.Layers.Count+1),1,1){Visible=false};layer.Image.Dispose();layer.Image=capture;doc.Layers.Add(layer);dirty=true;RefreshLayers();threeDCaptureInfo.Text=layer.Name+" added as a hidden pixel layer. Use its eye icon to show it.";UpdateStatus();}catch(Exception error){MessageBox.Show(this,"The canvas could not be captured.\n\n"+error.Message,"Capture canvas");}finally{UseWaitCursor=false;}}
}
}
